"use client";

import { useState } from "react";
import { Badge, type BadgeProps } from "../../../components/vip-ui/badge";
import {
  Card,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../../components/vip-ui/card";
import {
  Cell,
  Column,
  Row,
  Table,
  TableBody,
  TableHeader,
} from "../../../components/vip-ui/table";
import { ToggleButton } from "../../../components/vip-ui/toggle-button";
import { ToggleButtonGroup } from "../../../components/vip-ui/toggle-button-group";
import { formatMoney, type OrderStatus, orders } from "./data";

const statusBadge: Record<
  OrderStatus,
  { label: string; variant: BadgeProps["variant"] }
> = {
  paid: { label: "Paid", variant: "success" },
  pending: { label: "Pending", variant: "warning" },
  refunded: { label: "Refunded", variant: "neutral" },
};

type Filter = "all" | OrderStatus;

export function RecentOrders() {
  const [filter, setFilter] = useState<Filter>("all");
  const visible = orders.filter(
    (order) => filter === "all" || order.status === filter,
  );

  return (
    <Card className="min-w-0 overflow-hidden">
      <CardHeader className="flex-row flex-wrap items-start justify-between gap-3 pb-4">
        <div className="grid gap-1">
          <CardTitle as="h2">Recent orders</CardTitle>
          <CardDescription>
            {visible.length} of {orders.length} orders from the last 3 days
          </CardDescription>
        </div>
        <ToggleButtonGroup
          aria-label="Order status"
          selectionMode="single"
          disallowEmptySelection
          selectedKeys={[filter]}
          onSelectionChange={(keys) => {
            const [next] = keys;
            if (next) setFilter(next as Filter);
          }}
        >
          <ToggleButton id="all" variant="segmented">
            All
          </ToggleButton>
          <ToggleButton id="paid" variant="segmented">
            Paid
          </ToggleButton>
          <ToggleButton id="pending" variant="segmented">
            Pending
          </ToggleButton>
        </ToggleButtonGroup>
      </CardHeader>
      <div className="overflow-x-auto">
        <Table aria-label="Recent orders" className="min-w-[560px]">
          <TableHeader>
            <Column isRowHeader className="ps-5">
              Customer
            </Column>
            <Column>Order</Column>
            <Column>Status</Column>
            <Column>Date</Column>
            <Column className="pe-5 text-end">Amount</Column>
          </TableHeader>
          <TableBody
            items={visible}
            renderEmptyState={() => (
              <p className="px-5 py-8 text-center text-sm text-muted-foreground">
                No orders have this status.
              </p>
            )}
          >
            {(order) => (
              <Row id={order.id}>
                <Cell className="ps-5">
                  <span className="block font-medium">{order.customer}</span>
                  <span className="block text-xs text-muted-foreground">
                    {order.email}
                  </span>
                </Cell>
                <Cell className="font-mono text-xs text-muted-foreground">
                  {order.id}
                </Cell>
                <Cell>
                  <Badge variant={statusBadge[order.status].variant}>
                    {statusBadge[order.status].label}
                  </Badge>
                </Cell>
                <Cell className="text-muted-foreground">{order.date}</Cell>
                <Cell className="pe-5 text-end font-medium tabular-nums">
                  {formatMoney(order.amount)}
                </Cell>
              </Row>
            )}
          </TableBody>
        </Table>
      </div>
    </Card>
  );
}

"use client";

import { areaY, defineChart, lineY } from "@tanstack/charts";
import { decorative } from "@tanstack/charts/mark/decorative";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import { scalePoint } from "@tanstack/charts/scales/point";
import { tooltip } from "@tanstack/charts/tooltip";
import { useMemo, useState } from "react";
import {
  Chart,
  ChartAction,
  ChartCaption,
  ChartDescription,
  ChartFrame,
  ChartTable,
  ChartTitle,
} from "../../../components/vip-ui/chart";
import { ToggleButton } from "../../../components/vip-ui/toggle-button";
import { ToggleButtonGroup } from "../../../components/vip-ui/toggle-button-group";
import { revenue } from "./data";

const periods = {
  "7": "Last 7 days",
  "14": "Last 14 days",
  "30": "Last 30 days",
} as const;
type Period = keyof typeof periods;

export function RevenueChart() {
  const [period, setPeriod] = useState<Period>("30");
  const rows = useMemo(() => revenue.slice(-Number(period)), [period]);
  const total = rows.reduce((sum, row) => sum + row.value, 0);
  const definition = useMemo(() => {
    const step = Math.ceil(rows.length / 7);
    const ticks = rows
      .filter((_, index) => (rows.length - 1 - index) % step === 0)
      .map((row) => row.day);
    return defineChart({
      marks: [
        decorative(
          areaY(rows, {
            id: "revenue-fill",
            x: "day",
            y: "value",
            fill: "var(--ts-chart-1)",
            fillOpacity: 0.16,
          }),
        ),
        lineY(rows, {
          id: "revenue-line",
          x: "day",
          y: "value",
          stroke: "var(--ts-chart-1)",
          strokeWidth: 2.5,
        }),
      ],
      scales: {
        x: { scale: scalePoint, axis: { ticks: { values: ticks } } },
        y: { scale: scaleLinear().domain([0, 4.5]), grid: true },
      },
      tooltip: {
        use: tooltip,
        content: ([point]) => ({
          title: point.datum.day,
          rows: [
            {
              label: "Revenue",
              value: `$${(point.datum.value * 1000).toLocaleString("en-US")}`,
              color: point.color,
            },
          ],
        }),
      },
    });
  }, [rows]);

  return (
    <ChartFrame className="shadow-[var(--shadow-card)] ring-1 ring-border/70">
      <ChartCaption>
        <ChartTitle>Revenue</ChartTitle>
        <ChartDescription>
          ${(total * 1000).toLocaleString("en-US")} in the{" "}
          {periods[period].toLowerCase()}
        </ChartDescription>
      </ChartCaption>
      <ChartAction>
        <ToggleButtonGroup
          aria-label="Revenue period"
          selectionMode="single"
          disallowEmptySelection
          selectedKeys={[period]}
          onSelectionChange={(keys) => {
            const [next] = keys;
            if (next === "7" || next === "14" || next === "30") setPeriod(next);
          }}
        >
          <ToggleButton id="7" variant="segmented">
            7 days
          </ToggleButton>
          <ToggleButton id="14" variant="segmented">
            14 days
          </ToggleButton>
          <ToggleButton id="30" variant="segmented">
            30 days
          </ToggleButton>
        </ToggleButtonGroup>
      </ChartAction>
      <Chart
        definition={definition}
        height={240}
        initialWidth={640}
        ariaLabel={`Daily revenue for the ${periods[period].toLowerCase()}, in thousands of dollars`}
      />
      <ChartTable
        caption="Daily revenue, in thousands of dollars"
        columns={["Day", "Revenue"]}
        rows={rows.map((row) => [row.day, row.value])}
      />
    </ChartFrame>
  );
}
